import { test, expect } from '@playwright/test';

test.describe('Focus Indicators on Interactive Elements', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/interactive-elements');
  });

  test('should display focus indicator when navigating with keyboard', async ({ page }) => {
    // Verify focus indicator is visible on the first interactive element
    const firstButton = page.getByRole('button', { name: /submit/i });
    await expect(firstButton).toBeVisible();
    await expect(firstButton).toHaveCSS('box-shadow', /0 0 0 2px rgba(0, 153, 255, 1)/);

    // Navigate to the second interactive element using Tab
    const secondLink = page.getByRole('link', { name: /about/i });
    await secondLink.focus();
    await expect(secondLink).toHaveCSS('box-shadow', /0 0 0 2px rgba(0, 153, 255, 1)/);

    // Navigate to the third interactive element using Tab
    const thirdInput = page.getByLabel(/email/i);
    await thirdInput.focus();
    await expect(thirdInput).toHaveCSS('box-shadow', /0 0 0 2px rgba(0, 153, 255, 1)/);

    // Verify focus indicator is visible on the fourth interactive element
    const fourthDropdown = page.getByRole('combobox', { name: /options/i });
    await fourthDropdown.focus();
    await expect(fourthDropdown).toHaveCSS('box-shadow', /0 0 0 2px rgba(0, 153, 255, 1)/);
  });

  test('should remove focus indicator when element loses focus', async ({ page }) => {
    // Focus on the first button
    const firstButton = page.getByRole('button', { name: /submit/i });
    await firstButton.focus();
    await expect(firstButton).toHaveCSS('box-shadow', /0 0 0 2px rgba(0, 153, 255, 1)/);

    // Tab to the second link
    const secondLink = page.getByRole('link', { name: /about/i });
    await secondLink.focus();
    await expect(secondLink).toHaveCSS('box-shadow', /0 0 0 2px rgba(0, 153, 255, 1)/);

    // Tab back to the first button
    await firstButton.focus();
    await expect(firstButton).toHaveCSS('box-shadow', /0 0 0 2px rgba(0, 153, 255, 1)/);

    // Press Enter to submit the form
    await firstButton.click();
    await expect(firstButton).not.toHaveCSS('box-shadow', /0 0 0 2px rgba(0, 153, 255, 1)/);

    // Verify focus is removed from the button after submission
    await expect(firstButton).not.toHaveCSS('box-shadow', /0 0 0 2px rgba(0, 153, 255, 1)/);
  });
});
